package com.lyrashop.audit.entity;
import java.time.Instant;import java.util.UUID;import org.hibernate.annotations.CreationTimestamp;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.annotations.SourceType;import org.hibernate.type.SqlTypes;import jakarta.persistence.*;
@Entity @Table(name="admin_audit_logs") public class AdminAuditLog{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@JdbcTypeCode(SqlTypes.BINARY) @Column(name="admin_id",nullable=false,length=16) private UUID adminId;@Column(nullable=false,length=10) private String method;@Column(nullable=false,length=500) private String path;@Column(name="response_status",nullable=false) private int responseStatus;@Column(name="ip_address",length=64) private String ipAddress;@Column(name="user_agent",length=500) private String userAgent;@CreationTimestamp(source=SourceType.DB) @Column(name="created_at",nullable=false) private Instant createdAt;protected AdminAuditLog(){}public AdminAuditLog(UUID adminId,String method,String path,int status,String ip,String agent){this.adminId=adminId;this.method=method;this.path=path;this.responseStatus=status;this.ipAddress=ip;this.userAgent=agent;}public Long getId(){return id;}public UUID getAdminId(){return adminId;}public String getMethod(){return method;}public String getPath(){return path;}public int getResponseStatus(){return responseStatus;}public String getIpAddress(){return ipAddress;}public String getUserAgent(){return userAgent;}public Instant getCreatedAt(){return createdAt;}}
